from time import monotonic
from settings import TTL_SECONDS, MAX_ENTRIES

class Cache:
    def __init__(self):
        self.items = {}

    def put(self, key, value):
        self.items[key] = (value, monotonic())
        if len(self.items) > MAX_ENTRIES:
            oldest = min(self.items, key=lambda item: self.items[item][1])
            del self.items[oldest]

    def get(self, key):
        entry = self.items.get(key)
        if entry is None:
            return None
        value, created = entry
        if monotonic() - created >= TTL_SECONDS:
            del self.items[key]
            return None
        return value

class TemporaryFailure(Exception):
    pass

class PermanentFailure(Exception):
    pass

def send(request):
    if request.get("broken"):
        raise PermanentFailure("invalid request")
    if request.get("busy"):
        raise TemporaryFailure("busy")
    return {"ok": True}

from time import sleep
from config import ATTEMPTS, BASE_DELAY
from transport import TemporaryFailure, send

def request(payload):
    for attempt in range(ATTEMPTS):
        try:
            return send(payload)
        except TemporaryFailure:
            if attempt + 1 == ATTEMPTS:
                raise
            sleep(BASE_DELAY * (2 ** attempt))

from policy import DEFAULT_ROLE

class Principal:
    def __init__(self, name, role=None):
        self.name = name
        self.role = role or DEFAULT_ROLE

class Admin(Principal):
    def __init__(self, name):
        super().__init__(name, "admin")

class Resource:
    def __init__(self, owner):
        self.owner = owner

from roles import Admin

def can_write(principal, resource):
    if principal.name == resource.owner:
        return True
    return isinstance(principal, Admin)

def can_read(principal, resource):
    return principal.name == resource.owner or principal.role in {"reader", "admin"}

def parse(line):
    name, raw = line.split(":")
    return name, int(raw)

from parser import parse

def import_lines(lines, on_error):
    accepted = []
    rejected = 0
    for line in lines:
        try:
            name, amount = parse(line)
        except (ValueError, TypeError) as error:
            rejected += 1
            on_error(line, error)
            continue
        accepted.append({"name": name, "amount": amount})
    return accepted, rejected

import { maxPending } from './config.js'

export class Queue {
  constructor() { this.pending = []; this.running = false }
  add(job) {
    if (this.pending.length >= maxPending) return false
    this.pending.push(job)
    return true
  }
  async drain(run, onDone) {
    if (this.running) return
    this.running = true
    try {
      while (this.pending.length) {
        const job = this.pending.shift()
        try { onDone(job, await run(job), null) }
        catch (error) { onDone(job, null, error) }
      }
    } finally { this.running = false }
  }
}

import { Queue } from './queue.js'
export const queue = new Queue()
export const submit = (job, run, done) => {
  if (!queue.add(job)) return Promise.resolve(false)
  return queue.drain(run, done).then(() => true)
}

export function discount(subtotal, member) {
  if (!member || subtotal < 100) return 0
  return Math.min(subtotal * 0.2, 30)
}

import { taxRate } from './config.js'
import { discount } from './discount.js'
export function total(subtotal, member) {
  const afterDiscount = subtotal - discount(subtotal, member)
  return Number((afterDiscount * (1 + taxRate)).toFixed(2))
}

import { routes } from './routes.js'
export function dispatch(path, send) {
  const handler = routes.get(path)
  if (!handler) return send({ status: 404, body: 'missing' })
  try { return send(handler()) }
  catch (error) { return send({ status: 500, body: 'failed' }) }
}

import { isEnabled } from './feature.js'
export function response(settings, userId) {
  return isEnabled(settings, userId) ? 'new' : 'old'
}

import type { Listener } from './types.js'
export class Emitter<T> {
  private listeners = new Set<Listener<T>>()
  subscribe(listener: Listener<T>): () => void {
    this.listeners.add(listener)
    return () => this.listeners.delete(listener)
  }
  emit(event: T): number {
    let failures = 0
    for (const listener of [...this.listeners]) {
      try { listener(event) }
      catch { failures += 1 }
    }
    return failures
  }
}

export class StockRecord {
  constructor(public readonly sku: string, protected quantity: number) {}
  available(): number { return this.quantity }
}

import { StockRecord } from './base.js'
import { warningThreshold } from './config.js'
export class WarehouseStock extends StockRecord {
  reserve(count: number): boolean {
    if (!Number.isInteger(count) || count <= 0 || count > this.quantity) return false
    this.quantity -= count
    return true
  }
  needsRestock(): boolean { return this.quantity < warningThreshold }
}

import { lifetimeMs } from './config.js'
export type Session = { token: string; expiresAt: number }
export function valid(session: Session, now: number): boolean {
  return Boolean(session.token) && session.expiresAt > now
}
export function issue(token: string, now: number): Session {
  return { token, expiresAt: now + lifetimeMs }
}

import { valid, type Session } from './session.js'
export function authorize(session: Session, now: number, next: () => void): boolean {
  if (!valid(session, now)) return false
  next()
  return true
}

import { columns } from './schema.js'
export type Row = { id: string; amount: number }
export function parseRow(cells: string[]): Row | null {
  if (cells.length !== columns.length) return null
  const amount = Number(cells[1])
  if (!Number.isFinite(amount)) return null
  return { id: cells[0].trim(), amount }
}

import { parseRow, type Row } from './parse.js'
export function importRows(lines: string[], onInvalid: (line: string) => void): Row[] {
  const rows: Row[] = []
  for (const line of lines) {
    const row = parseRow(line.split(','))
    if (row) rows.push(row)
    else onInvalid(line)
  }
  return rows
}
